                Vector256<byte> revLo = Avx2.Shuffle(nibLut, lo);
                Vector256<byte> revHi = Avx2.Shuffle(nibLut, hi);

                Vector256<byte> result = Avx2.Or(
                    Avx2.ShiftLeftLogical(revLo.AsUInt16(), 4).AsByte(), revHi);

