            Vector128<byte> mask = Vector128.Create((byte)0x0F);
            Vector128<byte> nibLut = NibbleLookup128;

            for (; i + 16 <= len; i += 16)
            {
                Vector128<byte> vec = Unsafe.ReadUnaligned<Vector128<byte>>(
                    ref Unsafe.Add(ref ptr, i));

                Vector128<byte> lo = Sse2.And(vec, mask);
                Vector128<byte> hi = Sse2.And(Sse2.ShiftRightLogical(
                    vec.AsUInt16(), 4).AsByte(), mask);

                Vector128<byte> revLo = Ssse3.Shuffle(nibLut, lo);
                Vector128<byte> revHi = Ssse3.Shuffle(nibLut, hi);

                Vector128<byte> result = Sse2.Or(
                    Sse2.ShiftLeftLogical(revLo.AsUInt16(), 4).AsByte(), revHi);

                Unsafe.WriteUnaligned(ref Unsafe.Add(ref ptr, i), result);
            }
        }
        else if (AdvSimd.Arm64.IsSupported)
        {
            Vector128<byte> mask = Vector128.Create((byte)0x0F);
            Vector128<byte> nibLut = NibbleLookup128;

            for (; i + 16 <= len; i += 16)
            {
                Vector128<byte> vec = Unsafe.ReadUnaligned<Vector128<byte>>(
                    ref Unsafe.Add(ref ptr, i));

                Vector128<byte> lo = AdvSimd.And(vec, mask);
                Vector128<byte> hi = AdvSimd.And(
                    AdvSimd.ShiftRightLogical(vec, 4), mask);

                Vector128<byte> revLo = AdvSimd.Arm64.VectorTableLookup(nibLut, lo);
                Vector128<byte> revHi = AdvSimd.Arm64.VectorTableLookup(nibLut, hi);

